import { readFileSync } from "node:fs";

import { expect, expectStatus, sample, test } from "../../fixtures";

test("Documents cannot be added to a vendor under review", { tag: "@DOC-06" }, async ({ apiAs, factory }) => {
  // Arrange: a vendor in review, with its three documents already uploaded and extracted
  const member = await apiAs("member");
  const { vendor, documents } = await factory.vendorInReview();
  const before = await expectStatus<{ id: string }[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);

  // Act: the member uploads a W-9 to the vendor under review
  const response = await member.post(`/api/vendors/${vendor.id}/documents`, {
    multipart: { kind: "w9", file: { name: "w9.txt", mimeType: "text/plain", buffer: readFileSync(sample("w9.txt")) } },
  });

  // Assert: the upload is rejected because the vendor is locked
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_locked");

  // The rejected upload is not stored: the vendor still holds only its original documents
  const after = await expectStatus<{ id: string }[]>(await member.get(`/api/vendors/${vendor.id}/documents`), 200);
  expect(after.map((d) => d.id).sort()).toEqual(before.map((d) => d.id).sort());
  expect(after.map((d) => d.id)).toContain(documents.w9.id);
  expect(after).toHaveLength(3);
});
